128	function isStructuredObject(value: unknown): value is Record<string, unknown> {
129		return Boolean(value) && typeof value === "object" && !Array.isArray(value);
130	}
131	
132	function hasResultData(value: unknown): value is Record<string, unknown> {
133		return isStructuredObject(value) && Object.keys(value).length > 0;
134	}
135	
136	function toolInfoFromHostContext(value: unknown): {
137		id: string | number;
138		name: string;
139	} | null {
140		if (!isStructuredObject(value) || !isStructuredObject(value.toolInfo))
141			return null;
142		const id = value.toolInfo.id;
143		const tool = value.toolInfo.tool;
144		if (
145			(typeof id !== "string" && typeof id !== "number") ||
146			!isStructuredObject(tool) ||
147			typeof tool.name !== "string"
148		) {
149			return null;
150		}
151		return { id, name: tool.name };
152	}
153	
154	function snapshotCapabilityFromMeta(value: unknown): string | null | undefined {
155		if (
156			!isStructuredObject(value) ||
