169			Object.entries(value).filter(
170				(entry): entry is [string, ViewStateValue] =>
171					typeof entry[1] === "boolean" ||
172					typeof entry[1] === "string" ||
173					(typeof entry[1] === "number" && Number.isFinite(entry[1])),
174			),
175		);
176	}
177	
178	function sameViewState(
179		left: McpAppViewState,
180		right: McpAppViewState,
181	): boolean {
182		const leftKeys = Object.keys(left);
183		const rightKeys = Object.keys(right);
184		return (
185			leftKeys.length === rightKeys.length &&
186			leftKeys.every((key) => left[key] === right[key])
187		);
188	}
