219		const [app, setApp] = useState<App | null>(null);
220		const [approvalCapability, setApprovalCapability] = useState<string | null>(
221			initialCompat.approvalCapability ?? null,
222		);
223		const hasLiveToolOutput = useRef(false);
224		const hasCurrentLifetimeToolResult = useRef(false);
225		const hasData = useRef(data !== null);
226		const resultExplicitlyCleared = useRef(false);
227		const dataRevision = useRef(data === null ? 0 : 1);
228		const toolCallId = useRef<string | number | null>(null);
229		const toolCallName = useRef<string | null>(null);
230		const snapshotCapability = useRef<string | null>(null);
231		const snapshotSaveInFlight = useRef(false);
232		const snapshotSavedKey = useRef<string | null>(null);
233		const snapshotRestores = useRef(new Map<string, Promise<boolean>>());
234		const snapshotRestoreCompleted = useRef(new Set<string>());
235		const viewStateRef = useRef<McpAppViewState>({});
236		const viewStateRevision = useRef(0);
237		const persistSnapshotStateRef = useRef<(() => void) | null>(null);
238		const saveStateTimer = useRef<number | null>(null);
239		const allowSpaHostedViews = hasSameOriginParent();
