241		useEffect(() => {
242			if (!isEmbedded) {
243				applyTheme(undefined);
244				return;
245			}
246	
247			const compatTargets = openAiCompatTargets();
248			const nextApp = new App(
249				{ name: "Lobu Interaction", version: "1.0.0" },
250				{},
251				{ autoResize: true, strict: true },
252			);
253			const transport = new PostMessageTransport(window.parent, window.parent);
254			let connected = false;
255			const snapshotStateKey = (
256				id: string | number | null,
257				name: string | null,
258				capability: string | null,
259				revision: number,
260			) => JSON.stringify([id, name, capability, revision]);
261			const persistSnapshotState = async () => {
262				const activeRestore = snapshotRestores.current.get(
263					JSON.stringify([
264						toolCallId.current,
265						toolCallName.current,
266						snapshotCapability.current,
267					]),
268				);
269				if (activeRestore) {
270					// A user can change disclosure or pagination state while hydration is
271					// still in flight. Never let the partial local map replace untouched
272					// persisted keys before the restore has merged them.
273					if (await activeRestore) await persistSnapshotState();
274					return;
275				}
276				const capability = snapshotCapability.current;
277				const id = toolCallId.current;
278				const name = toolCallName.current;
279				const revision = viewStateRevision.current;
280				const stateKey = snapshotStateKey(id, name, capability, revision);
281				if (
282					(id === null && !capability) ||
283					(!capability && revision === 0) ||
284					snapshotSaveInFlight.current ||
285					snapshotSavedKey.current === stateKey
