287					return;
288				snapshotSaveInFlight.current = true;
289				try {
290					const result = await nextApp.callServerTool({
291						name: "save_lobu_app_state",
292						arguments: {
293							...(id === null ? {} : { tool_call_id: id }),
294							...(name ? { tool_name: name } : {}),
295							view_state: viewStateRef.current,
296							...(capability ? { snapshot_capability: capability } : {}),
297						},
298						...(capability
299							? {
300									_meta: {
301										"lobu/mcp-app-snapshot-capability": capability,
302									},
303								}
304							: {}),
305					});
306					const saved =
307						result.isError !== true &&
308						isStructuredObject(result.structuredContent) &&
309						result.structuredContent.saved === true;
310					if (
311						saved &&
312						snapshotCapability.current === capability &&
313						toolCallId.current === id &&
314						toolCallName.current === name &&
315						viewStateRevision.current === revision
