355				if (
356					(hasData.current && !allowDataPresent) ||
357					resultExplicitlyCleared.current
358				)
359					return Promise.resolve(false);
360				const capability = snapshotCapability.current;
361				const id = toolCallId.current;
362				const name = toolCallName.current;
363				const dataRevisionAtStart = dataRevision.current;
364				const viewStateRevisionAtStart = viewStateRevision.current;
365				if (id === null && !capability) return Promise.resolve(false);
366				const restoreKey = JSON.stringify([id, name, capability]);
367				const activeRestore = snapshotRestores.current.get(restoreKey);
368				if (activeRestore) return activeRestore;
369				if (snapshotRestoreCompleted.current.has(restoreKey)) {
370					return Promise.resolve(true);
371				}
372				const restore = Promise.resolve().then(async () => {
373					try {
374						const result = await nextApp.callServerTool({
375							name: "restore_lobu_app_result",
376							arguments: {
377								...(id === null ? {} : { tool_call_id: id }),
378								...(name ? { tool_name: name } : {}),
379								...(capability ? { snapshot_capability: capability } : {}),
380							},
381						});
382						if (
383							(!allowDataPresent && hasData.current) ||
384							(dataRevision.current !== dataRevisionAtStart &&
385								(!allowDataPresent || capability === null)) ||
386							snapshotCapability.current !== capability ||
387							toolCallId.current !== id ||
388							toolCallName.current !== name
389						) {
390							return false;
391						}
392						if (!isStructuredObject(result.structuredContent)) return false;
393						const restored = result.structuredContent;
394						if (restored.found === false) {
395							snapshotRestoreCompleted.current.add(restoreKey);
396							return true;
397						}
398						if (restored.found !== true || !hasResultData(restored.data))
399							return false;
400						snapshotRestoreCompleted.current.add(restoreKey);
401						const nextData = restored.data as T;
402						const restoredState = restoredViewState(restored.view_state);
403						const currentState = viewStateRef.current;
404						const changedDuringRestore =
