419							viewStateRevision.current += 1;
420						}
421						if (!hasData.current) {
422							dataRevision.current += 1;
423							hasData.current = true;
424							setData(nextData);
425							persistOpenAiData(compatTargets, nextData);
426						}
427						if (typeof restored.tool_name === "string") {
428							toolCallName.current = restored.tool_name;
429							setToolName(restored.tool_name);
430						}
431						return true;
432					} catch {
433						console.warn("[mcp-app] failed to restore result snapshot");
