643			setApp(nextApp);
644			void nextApp
645				.connect(transport)
646				.then(async () => {
647					connected = true;
648					const hostContext = nextApp.getHostContext();
649					applyTheme(hostContext?.theme);
650					const info = toolInfoFromHostContext(hostContext);
651					if (info) {
652						toolCallId.current = info.id;
653						toolCallName.current = info.name;
654						setToolName(info.name);
655					}
656					if (hasCurrentLifetimeToolResult.current) {
657						if (hasLiveToolOutput.current) await persistSnapshotState();
658					} else {
659						const restored = await restoreSnapshot({
660							allowDataPresent: hasData.current,
661						});
662						if (restored && hasLiveToolOutput.current)
663							await persistSnapshotState();
664					}
665				})
666				.catch((error) => {
667					console.error("[mcp-app] failed to initialize", error);
668				});
669	
670			return () => {
671				nextApp.removeEventListener("toolresult", onToolResult);
672				nextApp.removeEventListener("hostcontextchanged", onHostContext);
673				for (const target of compatTargets) {
674					target.removeEventListener(
675						OPENAI_SET_GLOBALS_EVENT,
676						onOpenAiSetGlobals,
677					);
678				}
679				void transport.close();
680				if (saveStateTimer.current !== null) {
681					window.clearTimeout(saveStateTimer.current);
682				}
683				persistSnapshotStateRef.current = null;
684			};
685		}, []);
686	
687		const setViewState = useCallback(
688			(key: string, value: ViewStateValue) => {
689				if (!key || key.length > 120) return;
690				const next = { ...viewStateRef.current, [key]: value };
691				viewStateRef.current = next;
692				viewStateRevision.current += 1;
693				setViewStateValue(next);
694				if (!app) return;
695				if (saveStateTimer.current !== null) {
696					window.clearTimeout(saveStateTimer.current);
697				}
698				saveStateTimer.current = window.setTimeout(() => {
699					saveStateTimer.current = null;
700					persistSnapshotStateRef.current?.();
701				}, 250);
702			},
703			[app],
704		);
705	
706		const callTool = async (name: string, args: ToolArgs) => {
707			if (!app) {
708				if (!isEmbedded) {
709					console.log("[mcp-app] tools/call", name, args);
710					setLastResult((last) => ({
711						isError: false,
712						seq: (last?.seq ?? 0) + 1,
713					}));
714				}
715				return;
716			}
717			try {
718				const result = await app.callServerTool({
719					name,
720					arguments: args,
721					...(name === "resolve_lobu_approval" && approvalCapability
722						? { _meta: { "lobu/approval-capability": approvalCapability } }
723						: {}),
724				});
725				if (isStructuredObject(result.structuredContent)) {
726					const nextData = result.structuredContent as T;
727					resultExplicitlyCleared.current = false;
728					hasLiveToolOutput.current = true;
729					hasCurrentLifetimeToolResult.current = true;
730					dataRevision.current += 1;
731					hasData.current = true;
732					setData(nextData);
733					persistOpenAiData(openAiCompatTargets(), nextData);
734				}
735				if (name === "resolve_lobu_approval" && result.isError !== true) {
736					setApprovalCapability(null);
737				}
738				setLastResult((last) => ({
739					isError: result.isError === true,
740					seq: (last?.seq ?? 0) + 1,
741				}));
742			} catch {
743				setLastResult((last) => ({
744					isError: true,
745					seq: (last?.seq ?? 0) + 1,
746				}));
747			}
